function selectNav(key: string) {
  if (key === 'mine') {
    uni.showModal({
      title: '退出登录',
      content: '确定退出当前账号吗？',
      success: res => {
        if (!res.confirm) return
        useFloodStore().logout()
        uni.reLaunch({ url: '/pages/login/index' })
      },
    })
    return
  }
  if (key !== 'workbench') uni.showToast({ title: '该模块暂未开放', icon: 'none' })
}

